WITH target_ranked AS MATERIALIZED(SELECT pb.id_level,pb.id_user,record.time,min(record.time) OVER(PARTITION BY pb.id_level) world_record_time,RANK() OVER(PARTITION BY pb.id_level ORDER BY record.time) placement_rank,COUNT(*) OVER(PARTITION BY pb.id_level) field_count FROM (SELECT * FROM public.personal_best_global WHERE record_eligible) pb JOIN (SELECT * FROM public.record WHERE record_eligible) record ON record.id=pb.id_record JOIN public."user" account ON account.id=pb.id_user WHERE pb.id_level=ANY($1) AND account.banned=false AND record.time>0),target AS MATERIALIZED(SELECT *,CASE WHEN field_count>1 THEN 1-(placement_rank-1)::double precision/(field_count-1) ELSE 0.5 END placement,CASE WHEN field_count>=20 THEN 1 ELSE 0 END target_contributed FROM target_ranked),leave_one_out AS MATERIALIZED(SELECT target.*,(5.0+aggregate.placement_sum-target.placement*target.target_contributed)/(10+aggregate.eligible_level_count-target.target_contributed) independent_skill FROM target JOIN public.player_skill_aggregate aggregate ON aggregate.id_user=target.id_user WHERE aggregate.eligible_level_count-target.target_contributed>=20),skill_ranked AS MATERIALIZED(SELECT *,PERCENT_RANK() OVER(PARTITION BY id_level ORDER BY independent_skill) skill_percentile FROM leave_one_out) SELECT id_level,count(*)::integer rated_player_count,corr(skill_percentile,placement)::double precision alignment,(percentile_cont(0.5) WITHIN GROUP(ORDER BY ln(time/world_record_time)) FILTER(WHERE skill_percentile BETWEEN 0.4 AND 0.6)-percentile_cont(0.5) WITHIN GROUP(ORDER BY ln(time/world_record_time)) FILTER(WHERE skill_percentile>=0.8))::double precision separation,percentile_cont(0.5) WITHIN GROUP(ORDER BY independent_skill) FILTER(WHERE placement_rank<=10)::double precision field_strength FROM skill_ranked GROUP BY id_level
